<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ ?>
<header class="section-heading"><div><span class="status">Tickets</span><h1>Novo ticket</h1><p class="meta">Abra uma demanda interna e indique quem será responsável.</p></div><a class="button-secondary" href="<?= $escape($basePath) ?>/tickets">Cancelar</a></header>
<?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/tickets"><?= $csrfField ?><div class="form-grid"><div class="form-field"><label for="ticket-unit">Unidade <span class="required">*</span></label><select id="ticket-unit" name="unit_id" required><option value="">Selecione</option><?php foreach($units as$unit):?><option value="<?= (int)$unit['id'] ?>"<?= (int)$selectedUnitId===(int)$unit['id']?' selected':'' ?>><?= $escape($unit['name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="ticket-assigned">Responsável <span class="required">*</span></label><select id="ticket-assigned" name="assigned_user_id" required><option value="">Selecione</option><?php foreach($responsibles as$user):?><option value="<?= (int)$user['id'] ?>" data-unit-id="<?= (int)$user['unit_id'] ?>"><?= $escape($user['name']) ?> · <?= $escape($user['unit_name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="ticket-priority">Prioridade <span class="required">*</span></label><select id="ticket-priority" name="priority" required><option value="normal">Normal</option><option value="low">Baixa</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></div><div class="form-field"><label for="ticket-due">Prazo</label><input id="ticket-due" name="due_at" type="datetime-local" min="<?= date('Y-m-d\TH:i') ?>"></div><div class="form-field form-field-wide"><label for="ticket-subject">Assunto <span class="required">*</span></label><input id="ticket-subject" name="subject" maxlength="180" required></div><div class="form-field form-field-wide"><label for="ticket-description">Descrição da demanda <span class="required">*</span></label><textarea id="ticket-description" name="description" rows="7" maxlength="10000" required></textarea></div></div><div class="form-actions"><button class="button-primary" type="submit"><i class="fa-solid fa-ticket"></i> Abrir ticket</button></div></form></div></section>
<script>document.addEventListener('DOMContentLoaded',()=>{const unit=document.querySelector('#ticket-unit');const assigned=document.querySelector('#ticket-assigned');if(!unit||!assigned)return;const filter=()=>{const selected=unit.value;Array.from(assigned.options).forEach((option,index)=>{if(index===0)return;option.hidden=selected!==''&&option.dataset.unitId!==selected;});if(assigned.selectedOptions[0]?.hidden)assigned.value='';};unit.addEventListener('change',filter);filter();});</script>
